'use strict';
let C,all,current,tab,state={version:1,answers:{},grades:{},review:{},history:[],profile:{}},db,recorder,stream,chunks=[],recordUrl,recordFor;
const KEY='catholicEnglish.unit1form.v2';const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(t){$('#status').textContent=t;$('#status').style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#status').style.display='none',2600)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch(e){notify('Chưa lưu được: bộ nhớ trình duyệt không khả dụng hoặc đã đầy. Hãy xuất bản sao lưu.');return false}}
function data(id){return state.answers[id]||(state.answers[id]={})}function grades(id){return state.grades[id]||(state.grades[id]={})}
function hasDone(id){return state.history.some(h=>h.id===id&&(all?.find(l=>l.id===id)?.format!==2||h.revision===2))}
function audio(l){return `<div class="audio-box"><h3>Nghe trước, đọc transcript sau</h3><small>Giọng tổng hợp Flite SLT · Anh-Mỹ · ${l.audioSeconds} giây. Nghe 2 lượt.</small><br><audio controls preload="none" src="${esc(l.audio)}" data-audio><a href="${esc(l.audio)}">Tải âm thanh</a></audio><div><label>Tốc độ <select data-speed><option value="0.8">0.8×</option><option value="1" selected>1×</option><option value="1.15">1.15×</option></select></label> · <a href="${esc(l.audio)}" download>Tải MP3</a></div><p class="error" data-audioerror hidden>Không phát được audio. Hãy tải MP3 hoặc thử trình duyệt khác.</p></div>`}
function rubric(skill,editable=false){return `<h3>Rubric ${skill} · Ngôn ngữ /8 + Nội dung /2</h3>${C.rubrics[skill].map((r,i)=>`<div class="rubric-row"><label>${esc(r[0])} · /2 ${editable?`<select class="grade" data-grade="${skill}-${i}" aria-label="${esc(skill+' '+r[0])}"><option value="">Chưa chấm</option>${[0,1,2].map(n=>`<option ${grades(current.id)[skill+'-'+i]===n?'selected':''} value="${n}">${n} / 2</option>`).join('')}</select>`:''}</label><p>${esc(r[2])}</p></div>`).join('')}`}
function nav(){const search=$('#search').value.toLowerCase();let previous='';$('#lesson-nav').innerHTML=C.lessons.filter(l=>(l.title+' '+l.vi+' '+l.focus+' '+l.vocab.map(v=>v.word).join(' ')).toLowerCase().includes(search)).map(l=>{let h=previous!==l.part?`<div class="group-label">PHẦN ${esc(l.part)}</div>`:'';previous=l.part;return h+`<a class="lesson-link ${current?.id===l.id?'active':''}" href="#lesson/${l.id}/learn" ${current?.id===l.id?'aria-current="page"':''}><span class="lesson-num">${hasDone(l.id)?'✓':l.id}</span><span>${esc(l.title)}</span></a>`}).join('')||'<p style="padding:20px">Không tìm thấy bài phù hợp.</p>'}
function home(){const done=C.lessons.filter(l=>hasDone(l.id)).length;const next=C.lessons.find(l=>!hasDone(l.id))||C.lessons[0];return `<section class="hero"><p class="eyebrow">CATHOLIC VOCABULARY & ECCLESIAL LANGUAGE</p><h1>Hiểu điều mình học.<br>Dùng điều mình hiểu.</h1><p>Một lộ trình tiếng Anh Công giáo gắn với đời sống cộng đoàn: học nghĩa trong ngữ cảnh, kết nối bốn kỹ năng và ôn lại từng bước.</p><div class="actions"><a class="button" href="#lesson/00/practice">Bắt đầu chẩn đoán ↗</a><a class="button secondary" href="#lesson/${next.id}/learn">${done?'Tiếp tục học':'Khám phá bài đầu'}</a></div></section><div class="stats"><div class="stat"><strong>26</strong><span>buổi theo syllabus · 52 giờ</span></div><div class="stat"><strong>4</strong><span>kỹ năng kết nối trong mỗi bài</span></div><div class="stat"><strong>${done}/26</strong><span>bài đã lưu một lượt làm</span></div></div><div class="callout"><strong>B1+ · Đang tiến tới B2.</strong> ${esc(C.level)}</div><div class="callout">Đã đổi theo mẫu Unit 1 bạn cung cấp: giáo trình song ngữ 8 phần, 20 mục từ, đề PDF và phiếu Word có dòng viết. <a href="Units_02_26_Theo_Mau_Unit1.zip" download>Tải trọn Unit 2–26</a>.</div><div class="sectionhead"><h2>Lộ trình của bạn</h2><a href="#mapping">Đối chiếu syllabus ↗</a></div><div class="cards">${[['I','Nền tảng ngôn ngữ Công giáo','01–08 · Giới thiệu, Kinh Thánh, Thiên Chúa, Giáo hội','01'],['II','Phụng vụ và bí tích','09–14 · Bí tích, không gian phụng vụ, Thánh lễ','09'],['III','Cầu nguyện và đời tu','15–20 · Cầu nguyện, ơn gọi, ngôn ngữ Dòng Tên','15'],['IV','Giao tiếp và học thuật','21–26 · Danh xưng, mục vụ, đọc và viết học thuật','21']].map(x=>`<article class="card"><span class="badge">PHẦN ${x[0]}</span><h3>${x[1]}</h3><p class="muted">${x[2]}</p><a href="#lesson/${x[3]}/learn">Vào phần học →</a></article>`).join('')}</div><div class="sectionhead"><h2>Dừng lại để nhìn tiến bộ</h2></div><div class="cards">${C.assessments.filter(l=>l.id!=='00').map(l=>`<article class="card"><span class="badge">${l.kind==='mock'?'THI THỬ · ĐỀ XUẤT':'ÔN TẬP'}</span><h3>${esc(l.title)}</h3><p>${esc(l.date)} · ${l.minutes} phút gợi ý</p><a href="#lesson/${l.id}/practice">Làm bài →</a></article>`).join('')}</div><div class="callout">Học liệu tự biên soạn theo syllabus, chưa được giảng viên phê duyệt. Chưa có đề thi, trọng số hay bài đọc chính thức. Không hứa đạt B2 sau khóa học.</div><div class="actions"><a class="button secondary" href="Catholic_English_Complete.zip" download>Tải toàn bộ website + mã nguồn</a><a href="#sources">Quyền sử dụng & chính sách AI</a></div>`}
function mapping(){return `<p class="eyebrow">COURSE ALIGNMENT</p><h1>Từ syllabus đến thực hành.</h1><p>Chuẩn đầu ra trong syllabus: dùng thuật ngữ đúng; nói và viết về đức tin, đời tu và mục vụ; đọc hiểu văn kiện Giáo hội và Dòng Tên. Hoạt động chi tiết dưới đây do học liệu đề xuất.</p><div class="table-scroll"><table><thead><tr><th>Bài / ngày gốc</th><th>Chủ đề syllabus</th><th>Nhiệm vụ bài học</th><th>Đánh giá đề xuất</th></tr></thead><tbody>${C.lessons.map(l=>`<tr><td><a href="#lesson/${l.id}/learn">${l.id} · ${esc(l.date)}</a></td><td>${esc(l.title)}</td><td>${esc(l.focus)}<br><small>Nghe tình huống, đọc hiểu, hỏi–đáp, viết cho người đọc cụ thể.</small></td><td>R01–R05 đọc; V01–V04 thuật ngữ tự luận; G01–G03 ngữ pháp; S01–S02 nói; W01 viết; C01 đọc phản biện; Unit 2–26 có L01–L03 nghe. Nội dung và ngôn ngữ chấm riêng.</td></tr>`).join('')}</tbody></table></div><h2>Thời lượng một buổi · 120 phút</h2><p>10 phút ôn · 20 phút đọc · 15 phút từ và phát âm · 20 phút nghe · 20 phút nói · 20 phút viết · 15 phút chữa và ôn.</p><div class="callout">${C.notes.slice(1,5).map(esc).join('<br>')}</div><p>Tài liệu bắt buộc theo syllabus: Bible, Vatican II documents, Jesuit texts, online sources. Tài liệu bổ sung: Catechism, Roman Missal, Liturgy of the Hours, Spiritual Exercises, nguồn Dòng Tên và USCCB. Chưa có ấn bản hoặc đoạn đọc được chỉ định; website không gán ngữ liệu tự biên soạn thành bài đọc chính thức.</p>`}
function sourcesPage(){return `<p class="eyebrow">SCOPE & SOURCES</p><h1>Học rõ nguồn, dùng đúng chỗ.</h1><p>${esc(C.templateNote)}</p><div class="box">${C.notes.map(x=>`<p>${esc(x)}</p>`).join('')}</div><h2>Tiếng Anh đầu vào</h2><p>${esc(C.level)}</p><p>${esc(C.diagnosticGuide)}</p><h2>Nguồn chính thức để đọc thêm</h2>${Object.values(C.sources).map(s=>`<p class="source"><a href="${esc(s.url)}" rel="noopener" target="_blank">${esc(s.title)}</a></p>`).join('')}<p class="source"><a href="https://www.usccb.org/prayer-and-worship/the-mass/general-instruction-of-the-roman-missal/girm-chapter-6" target="_blank" rel="noopener">GIRM Chapter VI · Phẩm phục, số 336–337</a></p><div class="box"><h2>Riêng tư trên thiết bị</h2><p>Website công khai. Câu trả lời, bài viết, ghi chú và điểm lưu trong localStorage của trình duyệt này. Bản ghi âm lưu trong IndexedDB trên thiết bị. Không có tài khoản, không đồng bộ và không gửi bài làm lên máy chủ.</p><p>Dùng chung hồ sơ trình duyệt thì có thể thấy dữ liệu của nhau. Xóa dữ liệu trình duyệt có thể xóa bài làm. Bản sao lưu JSON có thể chứa bài viết và âm thanh riêng tư; giữ ở nơi bạn kiểm soát.</p><p>Ghi âm cần trình duyệt hỗ trợ và quyền dùng micro. Không có chấm phát âm, chấm nói hoặc chấm viết tự động. Các điểm rubric là do bạn hoặc giáo viên nhập.</p><a href="#progress">Xuất/nhập bản sao lưu →</a></div>`}
function legacyDownloadLink(l){let idx=tab==='learn'?0:tab==='tasks'?1:2;return `<a class="button secondary" href="pdf/${esc(l.pdfs[idx])}" download>Tải PDF · ${['Giáo trình','Đề bài','Phiếu luyện tập'][idx]} ↓</a>`}
function legacyLearn(l){return `<div class="actions">${downloadLink(l)}<a href="#lesson/${l.id}/practice">Vào luyện tập →</a></div><section><h2>Bạn đang học gì?</h2><ul>${l.objectives.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="callout">${esc(l.explain)}</div><h2>Từ vựng có ngữ cảnh</h2><div class="vocab-grid">${l.vocab.map(v=>`<article class="vocab"><strong lang="en">${esc(v.word)}</strong> <span class="ipa">${esc(v.ipa)}</span><br><small>${esc(v.pos)} · ${esc(v.meaning)}</small><p class="example" lang="en">${esc(v.example)}</p><p><small>Cụm dùng: ${esc(v.collocation)}</small></p></article>`).join('')}</div><h2>Đọc để hiểu bối cảnh</h2><p class="reading" lang="en">${esc(l.reading)}</p><details><summary>Gợi ý đọc và ví dụ có hướng dẫn</summary><p>Xác định ai nói với ai, đang cần làm gì. Gạch chân một chi tiết giúp bạn hiểu vai trò hoặc giới hạn. Tóm tắt ý chính trước khi dịch từ khó.</p><p lang="en">${esc(l.vocab[0].example)}</p><p>Từ <strong>${esc(l.vocab[0].word)}</strong> ở đây mang nghĩa ${esc(l.vocab[0].meaning)}. Ghi cả cụm <em>${esc(l.vocab[0].collocation)}</em>, rồi tự đặt một câu với tình huống khác.</p></details><h2>Mẫu câu và phát âm</h2><div class="box"><p>${esc(l.grammar)}</p><p>${esc(l.pronunciation)}</p></div>${audio(l)}<details><summary>Chủ động xem transcript · nên nghe trước</summary><p lang="en">${esc(l.script)}</p></details><h2>Điều chỉnh mức hỗ trợ</h2><details><summary>Củng cố · có khung câu và hỗ trợ</summary><p>${esc(l.support)}</p></details><details><summary>Nâng cao · giảm hỗ trợ</summary><p>${esc(l.stretch)}</p></details><div class="box"><h3>Lỗi dễ gặp và cách ôn</h3><p>Đừng dịch một từ rồi dùng cho mọi tình huống. Kiểm tra nghĩa, người nghe và trách nhiệm của người nói. Viết câu ngắn đúng ý trước khi thêm cấu trúc khó.</p><p>Ôn sau 1–3–7 ngày: nhớ lại 4 từ không nhìn tài liệu; nghe lại trước khi mở transcript; nói 60–90 giây; sửa hai lỗi trong đoạn viết.</p></div>${l.id==='00'?`<div class="callout">${esc(C.diagnosticGuide)}</div>`:''}<p class="source">Đọc thêm: <a href="${C.sources[l.source].url}" target="_blank" rel="noopener">${esc(C.sources[l.source].title)}</a>. Các đoạn đọc và audio trong bài là ngữ liệu tự biên soạn.</p><details><summary>Chủ động xem phụ lục đáp án và rubric</summary>${answers(l)}${rubric('Speaking')}${rubric('Writing')}</details></section>`}
function answers(l){return `<h3>Đáp án gợi ý · chấp nhận cách diễn đạt tương đương</h3>${l.questions.map(q=>`<div class="answer"><strong>${q.code}</strong><p>${esc(q.type==='mc'?String.fromCharCode(65+q.answer)+'. '+q.options[q.answer]:q.answer)}</p><small>${esc(q.explanation)}</small></div>`).join('')}`}
function question(q,editable){let a=data(current.id),v=a[q.code]??'';let ret=`<div class="q" id="q-${q.code}"><fieldset><legend><span class="badge">${q.code} · ${q.points} điểm</span> ${esc(q.prompt)}</legend>`;
 if(q.type==='mc')ret+=`<div class="opts">${q.options.map((o,i)=>`<label class="opt"><input type="radio" name="${q.code}" data-answer="${q.code}" value="${i}" ${Number(v)===i&&v!==''?'checked':''} ${editable?'':'disabled'}><span>${String.fromCharCode(65+i)}. ${esc(o)}</span></label>`).join('')}</div>`;
 else if(editable)ret+=`<label class="sr" for="answer-${q.code}">${esc(q.code+' '+q.skill)}</label><textarea id="answer-${q.code}" class="${q.type==='writing'?'writing':''}" data-answer="${q.code}" placeholder="${q.type==='speaking'?'Ghi dàn ý, từ khóa và câu hỏi tiếp nối…':'Viết câu trả lời của bạn…'}">${esc(v)}</textarea><div class="meta-line"><span>${q.type==='speaking'?'Ghi chú nói; không phải bản chấm phát âm.':'Tự lưu trên trình duyệt.'}</span><span data-count="${q.code}">${words(v)} từ</span></div>`;
 ret+='</fieldset>';
 if(editable)ret+=`<label class="review"><input type="checkbox" data-review="${q.code}" ${state.review[current.id+'-'+q.code]?'checked':''}>Đánh dấu cần ôn lại</label>`;
 return ret+'</div>'}
function words(s){return String(s).trim()?String(s).trim().split(/\s+/).length:0}
function legacyTasks(l,editable){return `<div class="actions">${downloadLink(l)}${editable?'<span class="muted" style="font-size:12px">Nháp tự lưu khi bạn nhập.</span>':`<a href="#lesson/${l.id}/practice">Nhập câu trả lời →</a>`}</div><div class="callout">${l.kind==='mock'?'Thi thử theo định dạng đề xuất, chưa phải cấu trúc thi chính thức. ':''}34 điểm/bài: trắc nghiệm /6, câu ngắn tự chấm /8, Speaking /10 và Writing /10. Thời gian gợi ý ${l.kind==='lesson'?'45':l.minutes} phút cho bộ nhiệm vụ; 120 phút là thời lượng toàn buổi học.</div>${editable?`<label class="check"><input type="checkbox" data-speakdone ${data(l.id).speakDone?'checked':''}>Tôi đã thực hiện phần nói (ghi âm hoặc nói trực tiếp).</label>`:''}<h2>Listening <span class="badge">4 điểm</span></h2>${audio(l)}${l.questions.filter(q=>q.skill==='Listening').map(q=>question(q,editable)).join('')}<h2>Reading <span class="badge">6 điểm</span></h2><p class="reading" lang="en">${esc(l.reading)}</p>${l.questions.filter(q=>q.skill==='Reading').map(q=>question(q,editable)).join('')}<h2>Vocabulary <span class="badge">4 điểm</span></h2>${l.questions.filter(q=>q.skill==='Vocabulary').map(q=>question(q,editable)).join('')}<h2>Speaking <span class="badge">10 điểm</span></h2>${l.questions.filter(q=>q.skill==='Speaking').map(q=>question(q,editable)).join('')}${editable?`<div class="recorder"><h3>Ghi âm để tự nghe lại</h3><p class="muted">Lưu trên thiết bị này. Micro cần quyền truy cập; chưa có chấm phát âm tự động.</p><div class="actions"><button type="button" id="rec-start">Bắt đầu ghi âm</button><button type="button" id="rec-stop" class="secondary" disabled>Dừng và lưu</button></div><p id="rec-status" role="status"></p><div id="recording"></div></div>`:''}<h2>Writing <span class="badge">10 điểm</span></h2>${l.questions.filter(q=>q.skill==='Writing').map(q=>question(q,editable)).join('')}${editable?`<p class="error" id="form-error" role="alert"></p><div class="actions"><button id="submit">Hoàn thành và lưu lượt làm</button><button id="reveal" class="secondary">Chủ động xem đáp án</button></div><div id="feedback" ${data(l.id).revealed?'':'hidden'}>${feedback(l)}</div>`:''}`}
function legacyFeedback(l){return `<div class="results"><strong>Trắc nghiệm: ${objective(l).score}/6</strong><p>Chỉ 5 câu trắc nghiệm được máy chấm. Đây không phải điểm tổng và không dùng để xác định CEFR.</p></div>${answers(l)}<details><summary>Xem transcript sau khi nghe</summary><p>${esc(l.script)}</p></details><h2>Tự chấm và nhận xét</h2><p>Câu ngắn: 2 = đủ ý đúng; 1 = đúng một phần; 0 = sai/chưa làm. Chấp nhận diễn đạt tương đương. Không tự cho 0 vì khác nguyên văn đáp án.</p>${l.questions.filter(q=>q.type==='short').map(q=>`<div class="rubric-row"><label>${q.code} · ${esc(q.skill)} <select class="grade" data-grade="${q.code}" aria-label="Tự chấm ${q.code}"><option value="">Chưa chấm</option>${[0,1,2].map(n=>`<option value="${n}" ${grades(l.id)[q.code]===n?'selected':''}>${n}/2</option>`).join('')}</select></label></div>`).join('')}${rubric('Speaking',true)}${rubric('Writing',true)}<label for="reflection">Ghi chú sửa lỗi cho lần sau</label><textarea id="reflection" data-answer="reflection">${esc(data(l.id).reflection||'')}</textarea><div class="actions"><button id="save-grades">Lưu kết quả tự chấm</button></div><p id="grade-summary">${gradeSummary(l)}</p>`}
function legacyObjective(l){let score=0,total=0;for(const q of l.questions.filter(q=>q.type==='mc')){total+=q.points;if(data(l.id)[q.code]!==undefined&&Number(data(l.id)[q.code])===q.answer)score+=q.points}return{score,total}}
function legacyScore(l){let o=objective(l).score,g=grades(l.id),keys=['L2','R1','R2','R3',...['Speaking','Writing'].flatMap(s=>[0,1,2,3,4].map(i=>s+'-'+i))];let graded=keys.filter(k=>Number.isInteger(g[k]));let self=graded.reduce((a,k)=>a+g[k],0);return{auto:o,self,graded:graded.length,complete:graded.length===14,total:o+self,grades:{...g}}}
function legacyGradeSummary(l){const s=score(l);return s.complete?`Tổng ${s.total}/34 gồm trắc nghiệm ${s.auto}/6 và tự chấm ${s.self}/28. Tách ngôn ngữ và nội dung trong rubric để chọn phần cần luyện.`:`Trắc nghiệm ${s.auto}/6. Đã tự chấm ${s.graded}/14 tiêu chí/câu; chưa có điểm tổng.`}
function lesson(l){return `<p class="eyebrow">${l.kind==='lesson'?`BÀI ${l.id} · PHẦN ${l.part}`:esc(l.part)} / ${esc(l.date)}</p><h1 class="lesson-title">${esc(l.title)}</h1><p class="muted">${esc(l.focus)}</p><nav class="tabs" aria-label="Ba mục của bài">${[['learn','Giáo trình'],['tasks','Đề bài'],['practice','Luyện tập']].map(x=>`<a class="${tab===x[0]?'active':''}" ${tab===x[0]?'aria-current="page"':''} href="#lesson/${l.id}/${x[0]}">${x[1]}</a>`).join('')}</nav>${tab==='learn'?learn(l):tasks(l,tab==='practice')}<div class="divider"></div><div class="actions">${l.kind==='lesson'&&l.number>1?`<a class="button secondary" href="#lesson/${String(l.number-1).padStart(2,'0')}/learn">← Bài trước</a>`:''}${l.kind==='lesson'&&l.number<26?`<a class="button secondary" href="#lesson/${String(l.number+1).padStart(2,'0')}/learn">Bài tiếp →</a>`:''}<a href="#home">Về khóa học</a></div>`}
function progressPage(){let marked=Object.keys(state.review).filter(k=>state.review[k]);return `<p class="eyebrow">YOUR PRIVATE WORKSPACE</p><h1>Tiến bộ được ghi lại.</h1><p>Bài làm và bản ghi âm chỉ lưu trên trình duyệt, không đồng bộ tài khoản. Xuất bản sao lưu trước khi đổi máy hoặc xóa dữ liệu trình duyệt.</p><div class="box"><h3>Hồ sơ đầu vào · chưa xác minh nếu để trống</h3><label>Loại TOEIC <select data-profile="toeicType"><option value="">Chưa rõ</option>${['Listening & Reading','Speaking & Writing','Khác'].map(v=>`<option ${state.profile.toeicType===v?'selected':''}>${v}</option>`).join('')}</select></label><div class="actions">${['Listening','Reading','Speaking','Writing'].map(k=>`<label>${k}<br><input style="width:100px" type="number" min="0" max="${['Listening','Reading'].includes(k)?495:200}" data-profile="${k}" value="${esc(state.profile[k]||'')}" aria-label="Điểm TOEIC ${k}"></label>`).join('')}</div><p class="muted">Không tự quy đổi từ tổng điểm. Dữ liệu này là bạn tự nhập, không phải phiếu điểm được xác minh.</p></div><div class="actions"><button id="export">Xuất sao lưu gồm âm thanh</button><label class="button secondary" for="import">Nhập bản sao lưu</label><input id="import" type="file" accept="application/json,.json" class="sr"></div><p id="backup-status" role="status"></p><h2>Câu cần ôn · ${marked.length}</h2>${marked.length?marked.map(k=>{const id=k.slice(0,k.lastIndexOf('-')),code=k.slice(k.lastIndexOf('-')+1),l=all.find(x=>x.id===id);return l?`<p><a href="#lesson/${id}/practice">${esc(l.title)} · ${code}</a></p>`:''}).join(''):'<p class="muted">Đánh dấu “cần ôn lại” bên dưới từng câu trong phần luyện tập.</p>'}<h2>Lịch sử · ${state.history.length} lượt</h2><div class="table-scroll"><table><thead><tr><th>Thời điểm</th><th>Bài</th><th>Trắc nghiệm</th><th>Tự chấm</th></tr></thead><tbody>${[...state.history].reverse().map(h=>`<tr><td>${esc(new Date(h.at).toLocaleString('vi-VN'))}</td><td><a href="#lesson/${h.id}/practice">${esc(all.find(x=>x.id===h.id)?.title||h.id)}</a>${h.revision===2?'':'<br><small>Lượt theo phiên bản trước</small>'}</td><td>${h.score.auto}/${h.score.autoMax||6}</td><td>${h.score.complete?h.score.total+'/'+(h.score.max||34)+' tổng':h.score.graded+'/'+(h.score.criterionCount||14)+' tiêu chí; chưa đủ điểm tổng'}<details><summary>Xem bài làm đã lưu</summary>${Object.entries(h.answers||{}).filter(([k,v])=>(/^[RVGLSWC]\d{1,2}$/.test(k)||k==='reflection')).map(([k,v])=>{let q=all.find(x=>x.id===h.id)?.questions.find(x=>x.code===k);let display=q?.type==='mc'?String.fromCharCode(65+Number(v))+'. '+(q.options[Number(v)]||''):v;return `<p><strong>${esc(k)}:</strong> ${esc(display)}</p>`}).join('')}</details></td></tr>`).join('')||'<tr><td colspan="4">Chưa có lượt làm đã lưu.</td></tr>'}</tbody></table></div><h2>Chọn mức hỗ trợ</h2><p>${esc(C.diagnosticGuide)}</p><details><summary>Xóa dữ liệu cá nhân trên thiết bị này</summary><p>Xuất sao lưu trước. Thao tác tiếp theo yêu cầu bạn xác nhận lại bằng hộp thoại.</p><button id="clear" class="secondary">Xóa bài làm và bản ghi âm</button></details>`}
async function route(){if(recorder?.state==='recording'){recorder.stop();notify('Đã dừng ghi âm khi chuyển trang.')}let parts=location.hash.slice(1).split('/');current=null;let html;
 if(parts[0]==='lesson'){current=all.find(l=>l.id===parts[1]);tab=['learn','tasks','practice'].includes(parts[2])?parts[2]:'learn';html=current?lesson(current):'<h1>Không tìm thấy bài.</h1><a href="#home">Về khóa học</a>'}
 else html=parts[0]==='mapping'?mapping():parts[0]==='sources'?sourcesPage():parts[0]==='progress'?progressPage():home();
 $('#main').innerHTML=html;nav();$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');bind();window.scrollTo(0,0);if(current&&tab==='practice')await showRecording(current.id)}
function bind(){document.querySelectorAll('[data-speed]').forEach(s=>s.addEventListener('change',()=>s.closest('.audio-box').querySelector('audio').playbackRate=Number(s.value)));document.querySelectorAll('[data-audio]').forEach(a=>a.addEventListener('error',()=>a.closest('.audio-box').querySelector('[data-audioerror]').hidden=false));
 document.querySelectorAll('[data-answer]').forEach(el=>el.addEventListener('input',()=>{data(current.id)[el.dataset.answer]=el.value;save();let counter=document.querySelector(`[data-count="${el.dataset.answer}"]`);if(counter)counter.textContent=words(el.value)+' từ'}));
 document.querySelectorAll('[data-review]').forEach(el=>el.addEventListener('change',()=>{state.review[current.id+'-'+el.dataset.review]=el.checked;save()}));
 document.querySelectorAll('[data-grade]').forEach(el=>el.addEventListener('change',()=>{if(el.value==='')delete grades(current.id)[el.dataset.grade];else grades(current.id)[el.dataset.grade]=Number(el.value);save();if($('#grade-summary'))$('#grade-summary').textContent=gradeSummary(current)}));
 $('[data-speakdone]')?.addEventListener('change',e=>{data(current.id).speakDone=e.target.checked;save()});
 $('#submit')?.addEventListener('click',()=>{let missing=current.questions.filter(q=>q.type!=='speaking'&&!(String(data(current.id)[q.code]??'').trim())).map(q=>q.code);if(!data(current.id).speakDone)missing.push('xác nhận đã nói');if(missing.length){$('#form-error').textContent='Còn thiếu: '+missing.join(', ')+'. Bạn vẫn có thể chủ động xem đáp án nếu muốn.';return}data(current.id).revealed=true;state.history.push({revision:current.format===2?2:1,id:current.id,at:new Date().toISOString(),score:score(current),answers:{...data(current.id)}});save();nav();reveal();notify('Đã lưu lượt làm. Nói và viết cần tự chấm theo rubric.');});
 $('#reveal')?.addEventListener('click',()=>{data(current.id).revealed=true;save();reveal()});
 $('#save-grades')?.addEventListener('click',()=>{const h=[...state.history].reverse().find(x=>x.id===current.id&&(current.format!==2||x.revision===2));if(h){h.score=score(current);h.answers={...data(current.id)};save();notify('Đã cập nhật điểm tự chấm cho lượt làm gần nhất.')}else notify('Đã lưu tự chấm vào nháp. Hoàn thành bài để lưu một lượt làm.');});
 $('#rec-start')?.addEventListener('click',startRecording);$('#rec-stop')?.addEventListener('click',()=>{if(recorder?.state==='recording')recorder.stop()});
 document.querySelectorAll('[data-profile]').forEach(el=>el.addEventListener('change',()=>{if(el.type==='number'&&!el.checkValidity()){el.reportValidity();return}state.profile[el.dataset.profile]=el.value;save()}));
 $('#export')?.addEventListener('click',exportBackup);$('#import')?.addEventListener('change',importBackup);$('#clear')?.addEventListener('click',async()=>{if(!confirm('Xóa toàn bộ bài làm và bản ghi âm trên trình duyệt này? Hãy đảm bảo bạn đã xuất sao lưu.'))return;state={version:1,answers:{},grades:{},review:{},history:[],profile:{}};save();try{await dbAction('readwrite',s=>s.clear())}catch(e){}route();notify('Đã xóa dữ liệu trên thiết bị này.')});}
function reveal(){const f=$('#feedback');f.hidden=false;f.innerHTML=feedback(current);bindFeedback();f.scrollIntoView({behavior:'smooth',block:'start'})}
function bindFeedback(){document.querySelectorAll('#feedback [data-grade]').forEach(el=>el.addEventListener('change',()=>{if(el.value==='')delete grades(current.id)[el.dataset.grade];else grades(current.id)[el.dataset.grade]=Number(el.value);save();$('#grade-summary').textContent=gradeSummary(current)}));$('#reflection')?.addEventListener('input',e=>{data(current.id).reflection=e.target.value;save()});$('#save-grades')?.addEventListener('click',()=>{const h=[...state.history].reverse().find(x=>x.id===current.id&&(current.format!==2||x.revision===2));if(h){h.score=score(current);h.answers={...data(current.id)};}save();notify(h?'Đã cập nhật điểm tự chấm.':'Đã lưu nháp tự chấm; chưa có lượt làm hoàn thành.')})}
function openDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open('CatholicEnglishAudio',1);req.onupgradeneeded=()=>req.result.createObjectStore('recordings',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function dbAction(mode,fn){if(!db)db=await openDb();return new Promise((resolve,reject)=>{const tx=db.transaction('recordings',mode);const req=fn(tx.objectStore('recordings'));tx.oncomplete=()=>resolve(req?.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
async function startRecording(){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){$('#rec-status').textContent='Trình duyệt chưa hỗ trợ ghi âm tại đây. Hãy dùng ứng dụng ghi âm của thiết bị và luyện nói trực tiếp.';return}let id=current.id;try{stream=await navigator.mediaDevices.getUserMedia({audio:true});if(current?.id!==id||tab!=='practice'){stream.getTracks().forEach(t=>t.stop());return}recorder=new MediaRecorder(stream);chunks=[];recordFor=id;recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=async()=>{const blob=new Blob(chunks,{type:recorder.mimeType});stream.getTracks().forEach(t=>t.stop());try{await dbAction('readwrite',s=>s.put({id,blob,at:new Date().toISOString()}));data(id).speakDone=true;save();if(current?.id===id&&tab==='practice'){if($('[data-speakdone]'))$('[data-speakdone]').checked=true;$('#rec-start').disabled=false;$('#rec-stop').disabled=true;$('#rec-status').textContent='Đã lưu bản ghi trên thiết bị. Bản mới thay bản cũ của bài này.';await showRecording(id)}notify('Đã lưu bản ghi âm.')}catch(e){notify('Không lưu được bản ghi. Hãy kiểm tra bộ nhớ trình duyệt.')}};recorder.start();$('#rec-start').disabled=true;$('#rec-stop').disabled=false;$('#rec-status').textContent='Đang ghi âm… Nhấn Dừng và lưu khi kết thúc.'}catch(e){$('#rec-status').textContent='Chưa truy cập được micro. Kiểm tra quyền micro, hoặc dùng ứng dụng ghi âm của thiết bị.'}}
async function showRecording(id){try{const record=await dbAction('readonly',s=>s.get(id));if(current?.id!==id||!$('#recording'))return;if(recordUrl)URL.revokeObjectURL(recordUrl);if(!record){$('#recording').innerHTML='';return}recordUrl=URL.createObjectURL(record.blob);$('#recording').innerHTML=`<small>Bản ghi gần nhất · ${esc(new Date(record.at).toLocaleString('vi-VN'))}</small><audio class="recorded" controls src="${recordUrl}"></audio><a href="${recordUrl}" download="Speaking_${id}.${record.blob.type.includes('mp4')?'m4a':'webm'}">Tải bản ghi riêng</a>`}catch(e){if($('#rec-status'))$('#rec-status').textContent='Không dùng được kho lưu âm thanh; bạn vẫn có thể luyện nói và nhập ghi chú.'}}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function asDataURL(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob)})}
async function exportBackup(){const status=$('#backup-status');status.textContent='Đang tạo bản sao lưu…';try{let recordings=[];try{recordings=await dbAction('readonly',s=>s.getAll())}catch(e){status.textContent='Không truy cập được kho ghi âm. Chưa xuất sao lưu; tải bản ghi riêng nếu còn hiển thị.';return}let audio=[];for(const r of recordings)audio.push({id:r.id,at:r.at,data:await asDataURL(r.blob)});download(new Blob([JSON.stringify({format:'CatholicEnglishBackup',version:1,exportedAt:new Date().toISOString(),state,recordings:audio})],{type:'application/json'}),'Catholic_English_Backup.json');status.textContent='Đã tạo bản sao lưu gồm bài làm và '+audio.length+' bản ghi âm. Tệp có dữ liệu cá nhân; hãy giữ riêng.'}catch(e){status.textContent='Không tạo được bản sao lưu: '+e.message}}
function legacyValidateBackup(b){if(b?.format!=='CatholicEnglishBackup'||b.version!==1||!b.state||!Array.isArray(b.recordings))throw Error('Không đúng định dạng sao lưu.');let s=b.state;if(s.version!==1||!s.answers||!s.grades||!s.review||!s.profile||!Array.isArray(s.history))throw Error('Thiếu dữ liệu hợp lệ.');const ids=new Set(all.map(l=>l.id));for(const [id,a]of Object.entries(s.answers)){if(!ids.has(id)||!a||typeof a!=='object'||Array.isArray(a))throw Error('Mã bài hoặc câu trả lời không hợp lệ.');for(const v of Object.values(a))if(!['string','number','boolean'].includes(typeof v))throw Error('Câu trả lời không hợp lệ.')}for(const[id,g]of Object.entries(s.grades)){if(!ids.has(id)||!g||Object.values(g).some(n=>!Number.isInteger(n)||n<0||n>2))throw Error('Điểm tự chấm không hợp lệ.')}for(const h of s.history){if(!ids.has(h.id)||!h.score||!Number.isFinite(Date.parse(h.at)))throw Error('Lịch sử không hợp lệ.');const p=h.score;if(!Number.isInteger(p.auto)||p.auto<0||p.auto>6||!Number.isInteger(p.self)||p.self<0||p.self>28||!Number.isInteger(p.total)||p.total!==p.auto+p.self||!Number.isInteger(p.graded)||p.graded<0||p.graded>14||typeof p.complete!=='boolean')throw Error('Điểm lịch sử không hợp lệ.');if(h.answers&&Object.values(h.answers).some(v=>!['string','number','boolean'].includes(typeof v)))throw Error('Bài lưu không hợp lệ.');}for(const r of b.recordings)if(!ids.has(r.id)||typeof r.data!=='string'||!/^data:audio\/[a-zA-Z0-9.+;-]+;base64,/.test(r.data))throw Error('Bản ghi âm không hợp lệ.');return b}
async function importBackup(e){const file=e.target.files[0];if(!file)return;let status=$('#backup-status');try{if(file.size>150*1024*1024)throw Error('Tệp lớn hơn 150 MB; hãy chia sẻ bản ghi âm riêng.');let b=validateBackup(JSON.parse(await file.text()));let records=[];for(const r of b.recordings){let response=await fetch(r.data);records.push({id:r.id,at:r.at,blob:await response.blob()})}if(!confirm('Nhập bản sao lưu sẽ thay bài làm và bản ghi âm hiện tại trên trình duyệt này. Tiếp tục?'))return;if(!db)db=await openDb();await new Promise((resolve,reject)=>{let tx=db.transaction('recordings','readwrite'),s=tx.objectStore('recordings');s.clear();records.forEach(r=>s.put(r));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});state=b.state;if(!save())throw Error('Không lưu được bài làm vào trình duyệt.');route();notify('Đã khôi phục bản sao lưu.')}catch(err){status.textContent='Chưa nhập được: '+err.message}e.target.value=''}
async function init(){try{C=await(await fetch('course.json?v=4')).json();all=[...C.assessments,...C.lessons];try{let stored=JSON.parse(localStorage.getItem(KEY));if(!stored){stored=JSON.parse(localStorage.getItem('catholicEnglish.v1'));if(stored){for(const id of Object.keys(stored.answers||{}))if(/^\d{2}$/.test(id)&&id!=='00')delete stored.answers[id].revealed;localStorage.setItem(KEY,JSON.stringify(stored));}}if(stored?.version===1&&stored.answers&&stored.grades&&stored.review&&stored.profile&&Array.isArray(stored.history))state=stored}catch(e){notify('Không đọc được dữ liệu cũ. Hãy nhập bản sao lưu nếu có.')}$('#search').addEventListener('input',nav);$('#menu').addEventListener('click',()=>{let open=$('#sidebar').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open))});window.addEventListener('hashchange',route);await route()}catch(e){$('#main').innerHTML='<h1>Chưa tải được học liệu.</h1><p>Hãy tải lại trang. Nếu chạy local, khởi chạy máy chủ theo README thay vì mở trực tiếp file HTML.</p>'}}
// Extended unit layout follows the user's supplied Unit 1 form.
function bi(pairs){return `<div class="bilingual"><div class="bi-head">ENGLISH</div><div class="bi-head">TIẾNG VIỆT</div>${pairs.map(p=>`<div lang="en">${esc(p[0])}</div><div lang="vi">${esc(p[1])}</div>`).join('')}</div>`}
function downloadLink(l){if(l.format!==2)return legacyDownloadLink(l);const i=tab==='learn'?0:tab==='tasks'?1:2;return `<a class="button secondary" href="${esc(l.downloads[i])}" download>Tải ${i===2?'Word':'PDF'} · ${['Giáo trình','Đề bài','Phiếu có dòng viết'][i]} ↓</a>`}
function learn(l){if(l.format!==2)return legacyLearn(l);if(l.providedTemplate)return `<div class="actions">${downloadLink(l)}<a href="#lesson/${l.id}/practice">Làm theo đề Unit 1 →</a></div><div class="callout">Ba file Unit 1 được giữ nguyên như bạn cung cấp. Bản mẫu có 16 nhiệm vụ /100 và chưa có Listening. Unit 2–26 bổ sung Listening, có 19 nhiệm vụ /100. Nhãn B1–B2 trong file gốc không chứng nhận trình độ.</div><iframe class="pdf-frame" src="${esc(l.downloads[0])}" title="Giáo trình Unit 1 do người học cung cấp"></iframe><p>Nếu trình duyệt không hiện PDF, dùng nút tải giáo trình phía trên.</p><h2>${esc(l.readingTitle)}</h2><div class="reading" lang="en">${l.reading.split('\n\n').map(p=>`<p>${esc(p)}</p>`).join('')}</div><details><summary>Chủ động xem đáp án gợi ý</summary>${answers(l)}</details>`;
 return `<div class="actions">${downloadLink(l)}<a href="#lesson/${l.id}/practice">Vào luyện tập →</a></div><p class="muted">Theo cấu trúc Unit 1 · 20 mục từ · B1+ củng cố · từng bước luyện lên B2</p><h2>1 Introduction and Learning Objectives</h2>${bi([l.intro])}<ul>${l.objectives.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="callout">Học liệu bổ trợ tự biên soạn. Ngày theo syllabus; phần nội dung chi tiết chưa được giảng viên xác nhận. Bài dài có thể làm ngoài giờ học.</div><h2>2 Essential Catholic Vocabulary</h2><p>MUST KNOW: nắm chắc · SHOULD KNOW: nên dùng được · ADVANCED: mở rộng.</p><div class="vocab-grid">${l.vocab.map(v=>`<article class="vocab"><span class="badge">${esc(v.priority)}</span><h3 lang="en">${esc(v.word)} <span class="ipa">${esc(v.ipa)}</span></h3><small>${esc(v.pos)} · ${esc(v.meaning)}</small><p lang="en">${esc(v.definition)}</p><p class="example" lang="en">${esc(v.example)}</p><small>Collocation: ${esc(v.collocation)}</small></article>`).join('')}</div><h2>3 Key Concepts and Distinctions</h2>${l.distinctions.map(x=>`<h3>${esc(x[0])}</h3>${bi([[x[1],x[2]]])}`).join('')}<h2>4 Grammar and Sentence Patterns</h2><div class="table-scroll"><table><thead><tr><th>Structure</th><th>Example</th><th>Giải thích</th></tr></thead><tbody>${l.patterns.map(x=>`<tr><td>${esc(x[0])}</td><td lang="en">${esc(x[1])}</td><td>${esc(x[2])}</td></tr>`).join('')}</tbody></table></div><div class="box"><p>${esc(l.grammar)}</p><p>${esc(l.pronunciation)}</p></div><h2>5 Reading and Comprehension</h2><h3>${esc(l.readingTitle)}</h3>${bi(l.readingPairs)}<p class="muted">Bài đọc tự biên soạn, tham khảo ${esc(l.reference)}. Bản tiếng Việt giải thích bài tự biên soạn, không phải bản dịch văn kiện hoặc kinh nguyện chính thức.</p><h2>6 Speaking and Writing Practice</h2><ul><li>S01: kịch bản 100–130 từ, chuẩn bị 2 phút, tập nói 60–90 giây.</li><li>S02: hội thoại 6 lượt, có hỏi làm rõ, giải thích từ và bước tiếp theo.</li><li>W01: viết 150–180 từ, đúng người đọc, có ví dụ và dẫn nguồn phù hợp.</li></ul><p>Tiến hành theo mã câu và yêu cầu đầy đủ trong mục Đề bài hoặc Luyện tập.</p>${audio(l)}<details><summary>Chủ động mở transcript sau khi nghe</summary><p lang="en">${esc(l.script)}</p></details><h2>7 Extended Catholic and Jesuit Knowledge</h2>${l.extension.map(x=>`<h3>${esc(x.theme)}</h3>${bi([[x.en,x.vi]])}<small>${esc(x.status)}</small>`).join('')}<h2>8 Summary and Active Recall</h2><ol>${l.recall.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><details><summary>Củng cố</summary><p>${esc(l.support)}</p></details><details><summary>Mở rộng</summary><p>${esc(l.stretch)}</p></details><p class="source"><a href="${esc(C.sources[l.source].url)}" target="_blank" rel="noopener">Nguồn chính thức để kiểm tra</a> · ${esc(l.reference)}</p><p>Ôn sau 1, 3 và 7 ngày. Không dùng học liệu thay các bài suy tư cá nhân, bài từ vựng trên lớp hoặc bài được đánh dấu AI-limited.</p><details><summary>Chủ động xem phụ lục đáp án và rubric</summary>${answers(l)}${criteriaGuide(l)}</details>`}
const UNIT_GROUPS=[['Reading','A Reading comprehension'],['Terminology','B Catholic terminology'],['Grammar','C Grammar in context'],['Speaking','D Speaking and community communication'],['Writing','E Academic and practical writing'],['Critical reading','F Critical reading'],['Listening','G Listening in context']];
function criteriaGuide(l){return l.questions.filter(q=>q.type!=='mc').map(q=>`<div class="box"><h3>${q.code} · ${q.points} điểm</h3>${q.criteria.map(r=>`<p><strong>${esc(r.label)} /${r.max}</strong><br>${esc(r.desc)}</p>`).join('')}</div>`).join('')}
function tasks(l,editable){if(l.format!==2)return legacyTasks(l,editable);return `<div class="actions">${downloadLink(l)}<a class="button secondary" href="units/Unit${l.number}/Unit${l.number}_Bo_3_file.zip" download>Tải bộ ba file</a></div><div class="callout">${l.questions.length} nhiệm vụ · 100 điểm tự học. ${l.providedTemplate?'Giữ đúng đề Unit 1 bạn cung cấp; chưa có Listening.':'Giữ cấu trúc R/V/G/S/W/C của mẫu, bổ sung Listening L01–L03.'} Máy chấm trắc nghiệm /${objective(l).total}; phần tự luận dùng rubric. Không phải cấu trúc hoặc trọng số thi thật.</div>${editable?`<label class="check"><input type="checkbox" data-speakdone ${data(l.id).speakDone?'checked':''}>Tôi đã thực hiện phần nói, gồm S01 và S02 (nói trực tiếp hoặc ghi âm).</label>`:''}${UNIT_GROUPS.map(([skill,name])=>{const qs=l.questions.filter(q=>q.skill===skill);if(!qs.length)return '';return `<section><h2>${name} <span class="badge">${qs.reduce((s,q)=>s+q.points,0)} điểm</span></h2>${skill==='Reading'?`<h3>${esc(l.readingTitle)}</h3><div class="reading" lang="en">${l.reading.split('\n\n').map(p=>`<p>${esc(p)}</p>`).join('')}</div>`:''}${skill==='Listening'?audio(l):''}${qs.map(q=>question(q,editable)).join('')}${editable&&skill==='Speaking'?`<div class="recorder"><h3>Ghi âm S01 và S02 để tự nghe lại</h3><p class="muted">Lưu trên thiết bị; bản mới thay bản cũ của unit này. Không có chấm phát âm tự động.</p><div class="actions"><button type="button" id="rec-start">Bắt đầu ghi âm</button><button type="button" id="rec-stop" class="secondary" disabled>Dừng và lưu</button></div><p id="rec-status" role="status"></p><div id="recording"></div></div>`:''}</section>`}).join('')}${editable?`<p id="form-error" class="error" role="alert"></p><div class="actions"><button id="submit">Hoàn thành và lưu lượt làm</button><button id="reveal" class="secondary">Chủ động xem đáp án</button></div><div id="feedback" ${data(l.id).revealed?'':'hidden'}>${feedback(l)}</div>`:`<p>Phiếu Word có cùng câu hỏi, bài đọc và lựa chọn với đề PDF, kèm dòng viết.</p>`}`}
function feedback(l){if(l.format!==2)return legacyFeedback(l);return `<div class="results"><strong>Trắc nghiệm ${objective(l).score}/${objective(l).total}</strong><p>Các câu tự luận chưa được máy chấm. Không quy đổi kết quả sang CEFR.</p></div>${answers(l)}${l.audio?`<details><summary>Xem transcript</summary><p lang="en">${esc(l.script)}</p></details>`:''}<h2>Tự chấm theo tiêu chí</h2>${l.questions.filter(q=>q.type!=='mc').map(q=>`<div class="box"><h3>${q.code} · ${q.points} điểm</h3>${q.criteria.map((r,i)=>{let key=q.code+':'+i;return `<div class="rubric-row"><label>${esc(r.label)} · /${r.max}<select class="grade" data-grade="${key}" aria-label="${esc(q.code+' '+r.label)}"><option value="">Chưa chấm</option>${Array.from({length:r.max+1},(_,n)=>`<option value="${n}" ${grades(l.id)[key]===n?'selected':''}>${n}/${r.max}</option>`).join('')}</select></label><p>${esc(r.desc)}</p></div>`}).join('')}</div>`).join('')}<label for="reflection">Ghi chú sửa lỗi</label><textarea id="reflection" data-answer="reflection">${esc(data(l.id).reflection||'')}</textarea><div class="actions"><button id="save-grades">Lưu kết quả tự chấm</button></div><p id="grade-summary">${gradeSummary(l)}</p>`}
function objective(l){return legacyObjective(l)}
function score(l){if(l.format!==2)return legacyScore(l);const o=objective(l),g=grades(l.id);let totalSelf=0,graded=0,criterionCount=0,catholic=0,language=0,task=0;for(const q of l.questions.filter(q=>q.type!=='mc'))for(let i=0;i<q.criteria.length;i++){const r=q.criteria[i],n=g[q.code+':'+i];criterionCount++;if(Number.isInteger(n)&&n>=0&&n<=r.max){graded++;totalSelf+=n;if(r.category==='catholic')catholic+=n;else if(r.category==='language')language+=n;else task+=n}}return{auto:o.score,autoMax:o.total,self:totalSelf,selfMax:100-o.total,total:o.score+totalSelf,max:100,graded,criterionCount,complete:graded===criterionCount,catholic,language,task,grades:{...g}}}
function gradeSummary(l){if(l.format!==2)return legacyGradeSummary(l);const s=score(l);return `${s.complete?'Tổng '+s.total+'/100. ':'Chưa đủ tự chấm: '+s.graded+'/'+s.criterionCount+' tiêu chí. '}Trắc nghiệm ${s.auto}/${s.autoMax}; nội dung/thuật ngữ ${s.catholic}; ngôn ngữ và nhiệm vụ ${s.language}; hiểu thông tin nghe ${s.task}. Đây là điểm tự đánh giá.`}
function validateBackup(b){if(b?.format!=='CatholicEnglishBackup'||b.version!==1||!b.state||!Array.isArray(b.recordings))throw Error('Không đúng định dạng sao lưu.');const s=b.state;if(s.version!==1||!s.answers||!s.grades||!s.review||!s.profile||!Array.isArray(s.history))throw Error('Thiếu dữ liệu hợp lệ.');const ids=new Set(all.map(l=>l.id));for(const[id,a]of Object.entries(s.answers)){if(!ids.has(id)||!a||typeof a!=='object'||Array.isArray(a)||Object.values(a).some(v=>!['string','number','boolean'].includes(typeof v)))throw Error('Câu trả lời không hợp lệ.')}for(const[id,g]of Object.entries(s.grades))if(!ids.has(id)||!g||typeof g!=='object'||Object.values(g).some(n=>!Number.isInteger(n)||n<0||n>24))throw Error('Điểm không hợp lệ.');for(const h of s.history){const p=h.score;if(!ids.has(h.id)||!p||!Number.isFinite(Date.parse(h.at))||!Number.isInteger(p.auto)||p.auto<0||p.auto>100||!Number.isInteger(p.self)||p.self<0||p.self>100||!Number.isInteger(p.total)||p.total!==p.auto+p.self||p.total>100||!Number.isInteger(p.graded)||p.graded<0||p.graded>100||typeof p.complete!=='boolean')throw Error('Lịch sử không hợp lệ.');if(h.answers&&Object.values(h.answers).some(v=>!['string','number','boolean'].includes(typeof v)))throw Error('Bài lưu không hợp lệ.')}for(const r of b.recordings)if(!ids.has(r.id)||typeof r.data!=='string'||!/^data:audio\/[a-zA-Z0-9.+;-]+;base64,/.test(r.data))throw Error('Bản ghi âm không hợp lệ.');return b}

init();
